/**
 * @description : Nav Bar – vertical left sidebar for institute_user
 *                Renders menu items based on cds permission flags (same
 *                mechanism as institute_portal).
 * @author : Bala Krishna
 * @date   : 16-01-2023  (redesigned Aug-2026)
 */

import React, { useContext, useRef, useLayoutEffect } from 'react';
import {
  FaBookOpen,
  FaMoneyBillAlt,
  FaUserCircle,
  FaTachometerAlt,
  FaSignOutAlt,
  FaUniversity,
} from 'react-icons/fa';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../App';
import { isExactMatch } from '../../services/commonUtills/FormValidations';


const SIDEBAR_SCROLL_KEY = 'user_sidebar_scroll';

const NavBar = ({ onOpenHomework }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { stateAuth, dispatchAuth } = useContext(AuthContext);
  const cds = stateAuth?.user?.cds || '';
  const user = stateAuth?.user || {};

  const menuRef = useRef(null);

  /* ── Preserve sidebar scroll position across navigations ── */
  useLayoutEffect(() => {
    const saved = sessionStorage.getItem(SIDEBAR_SCROLL_KEY);
    if (saved && menuRef.current) {
      menuRef.current.scrollTop = parseInt(saved, 10);
    }
  }, [location.pathname]);

  const onScroll = () => {
    if (menuRef.current) {
      sessionStorage.setItem(SIDEBAR_SCROLL_KEY, menuRef.current.scrollTop);
    }
  };

  const isActive = (path) => location.pathname === path;

  const handleLogout = () => {
    dispatchAuth({ type: 'LOGOUT' });
    navigate('/');
  };

  const getInitials = () => {
    const name = user.stfnm || user.stdnm || user.drvnm || 'User';
    return name
      .split(' ')
      .filter(Boolean)
      .map((s) => s[0])
      .slice(0, 2)
      .join('')
      .toUpperCase();
  };

  return (
    <nav className="user-nav-sidebar">
      {/* ── Brand ── */}
      <div className="user-nav-brand">
        <div className="user-nav-brand-icon">
          <FaUniversity />
        </div>
        <div className="user-nav-brand-text">
          <h4>{user.instnm || 'Institute Portal'}</h4>
          <span>{user.brcnm || ''}</span>
        </div>
      </div>

      {/* ── Menu ── */}
      <div className="user-nav-menu-wrapper" ref={menuRef} onScroll={onScroll}>
        <ul className="user-nav-menu-list">

          {/* Section: Main */}
          <li><span className="user-nav-section-title">MAIN</span></li>

          {/* Dashboard – always visible */}
          <li className={`user-nav-menu-item${isActive('/dashboard') ? ' active' : ''}`}>
            <Link to="/dashboard" className="user-nav-menu-link">
              <FaTachometerAlt className="menu-icon" />
              <span>Dashboard</span>
            </Link>
          </li>

          {/* User / Staff Info */}
          {isExactMatch(cds, 'I_N_U_S') && (
            <>
              <li><span className="user-nav-section-title">INFORMATION</span></li>
              <li className={`user-nav-menu-item${isActive('/profile') ? ' active' : ''}`}>
                <Link to="/profile" className="user-nav-menu-link">
                  <FaUserCircle className="menu-icon" />
                  <span>My Profile</span>
                </Link>
              </li>
            </>
          )}

          {/* Home Work */}
          {isExactMatch(cds, 'H_W_M') && (
            <>
              <li><span className="user-nav-section-title">ACADEMICS</span></li>
              <li className="user-nav-menu-item">
                <button
                  className="user-nav-menu-link user-nav-menu-btn"
                  onClick={() => onOpenHomework && onOpenHomework()}
                >
                  <FaBookOpen className="menu-icon" />
                  <span>Home Work</span>
                </button>
              </li>
            </>
          )}

          {/* Payslip / Finance */}
          {isExactMatch(cds, 'P_F') && (
            <>
              <li><span className="user-nav-section-title">FINANCE</span></li>
              <li className={`user-nav-menu-item${isActive('/payslip') ? ' active' : ''}`}>
                <Link to="/payslip" className="user-nav-menu-link">
                  <FaMoneyBillAlt className="menu-icon" />
                  <span>Payslip</span>
                </Link>
              </li>
            </>
          )}

        </ul>
      </div>

      {/* ── Footer ── */}
      <div className="user-nav-footer">
        <div className="user-nav-user-row">
          <div className="user-nav-avatar-sm">{getInitials()}</div>
          <div className="user-nav-user-info">
            <span className="user-nav-user-name">
              {user.stfnm || user.stdnm || user.drvnm || 'User'}
            </span>
            <span className="user-nav-user-role">
              {user.typ === 'STAFF'
                ? 'Staff'
                : user.typ === 'STUDENT'
                ? 'Student'
                : user.typ || 'User'}
            </span>
          </div>
        </div>
        <div
          className="user-nav-support-card"
          onClick={handleLogout}
          title="Logout"
        >
          <span className="user-nav-support-icon"><FaSignOutAlt /></span>
          <div className="user-nav-support-text">
            <h5>Logout</h5>
            <span>End your session</span>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default NavBar;
